VALUES ('doc-09-mitre-attack-p0-20495', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-19T23:56:41.592Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PinchDuke](https://attack.mitre.org/software/S0048) steals credentials from compromised hosts. [PinchDuke](https://attack.mitre.org/software/S0048)''s credential stealing functionality is believed to be based on the source code of the Pinch credential stealing malware (also known as LdPinch). Credentials targeted by [PinchDuke](https://attack.mitre.org/software/S0048) include ones associated with many sources such as The Bat!, Yahoo!, Mail.ru, Passport.Net, Google Talk, and Microsoft Outlook.(Citation: F-Secure The Dukes)", "external_references": [{"description": "F-Secure Labs. (2015, September 17). The Dukes: 7 years of Russian cyberespionage. Retrieved December 10, 2015.", "source_name": "F-Secure The Dukes", "url": "https://www.f-secure.com/documents/996508/1030745/dukes_whitepaper.pdf"}], "id": "relationship--c23fa4f7-84a0-424a-b8b1-b3024d01e749", "modified": "2026-04-29T14:23:06.191Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--ae9d818d-95d0-41da-b045-9cabea1ca164", "spec_version": "2.1", "target_ref": "attack-pattern--3fc9b85a-2862-4363-a64d-d692e3ffbee0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20495', 0, 107, '09-mitre-attack', 'retrieved', 'DA2DAD7C7490CD98D13B6E70C05EE080470A916E4F57C71A74FF1C945274EA48', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
