VALUES ('doc-09-mitre-attack-p0-20516', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-07T17:40:04.685Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Milan](https://attack.mitre.org/software/S1015) can delete files via `C:\\Windows\\system32\\cmd.exe /c ping 1.1.1.1 -n 1 -w 3000 > Nul & rmdir /s /q`.(Citation: ClearSky Siamesekitten August 2021)", "external_references": [{"description": "ClearSky Cyber Security . (2021, August). New Iranian Espionage Campaign By “Siamesekitten” - Lyceum. Retrieved June 6, 2022.", "source_name": "ClearSky Siamesekitten August 2021", "url": "https://www.clearskysec.com/siamesekitten/"}], "id": "relationship--dd4ab207-a8d7-4b33-94bf-be87635cc853", "modified": "2026-04-29T14:23:06.227Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--aea6d6b8-d832-4c90-a1bb-f52c6684db6c", "spec_version": "2.1", "target_ref": "attack-pattern--d63a3fb8-9452-4e9d-a60a-54be68d5998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20516', 0, 79, '09-mitre-attack', 'retrieved', 'E11336C13190E69AD3DA40F62A2C0B72F00B1F3B867C77CEA96BF00B23B4DC6B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
