VALUES ('doc-09-mitre-attack-p0-20517', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-14T18:25:44.072Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Milan](https://attack.mitre.org/software/S1015) has used an executable named `companycatalog.exe.config` to appear benign.(Citation: ClearSky Siamesekitten August 2021)", "external_references": [{"description": "ClearSky Cyber Security . (2021, August). New Iranian Espionage Campaign By “Siamesekitten” - Lyceum. Retrieved June 6, 2022.", "source_name": "ClearSky Siamesekitten August 2021", "url": "https://www.clearskysec.com/siamesekitten/"}], "id": "relationship--eb76155e-39de-4952-857b-bf53a1586810", "modified": "2026-04-29T14:23:06.246Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--aea6d6b8-d832-4c90-a1bb-f52c6684db6c", "spec_version": "2.1", "target_ref": "attack-pattern--11f29a39-0942-4d62-92b6-fe236cf3066e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20517', 0, 70, '09-mitre-attack', 'retrieved', '2D6980BE05B6361CB8D6F083F610D803A3C92A74E52350848D078D5A76DBC5D6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
