VALUES ('doc-09-mitre-attack-p0-20528', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[USBStealer](https://attack.mitre.org/software/S0136) drops itself onto removable media and relies on Autorun to execute the malicious file when a user opens the removable media on another system.(Citation: ESET Sednit USBStealer 2014)", "external_references": [{"description": "Calvet, J. (2014, November 11). Sednit Espionage Group Attacking Air-Gapped Networks. Retrieved January 4, 2017.", "source_name": "ESET Sednit USBStealer 2014", "url": "http://www.welivesecurity.com/2014/11/11/sednit-espionage-group-attacking-air-gapped-networks/"}], "id": "relationship--e3e841fa-b806-4c22-9f98-a97950b68931", "modified": "2026-04-29T14:23:06.235Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--af2ad3b7-ab6a-4807-91fd-51bcaff9acbb", "spec_version": "2.1", "target_ref": "attack-pattern--3b744087-9945-4a6f-91e8-9dbceda417a4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20528', 0, 82, '09-mitre-attack', 'retrieved', '606169387DE6C9BE84562518DBA5A55DB4203DB4F28806DD71F4FF2EACFAA9B5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
