VALUES ('doc-09-mitre-attack-p0-20540', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-02T14:13:22.903Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OSX_OCEANLOTUS.D](https://attack.mitre.org/software/S0352) uses a shell script as the main executable inside an app bundle and drops an embedded base64-encoded payload to the /tmp folder.(Citation: Trend Micro MacOS Backdoor November 2020)(Citation: sentinelone apt32 macOS backdoor 2020)", "external_references": [{"description": "Magisa, L. (2020, November 27). New MacOS Backdoor Connected to OceanLotus Surfaces. Retrieved December 2, 2020.", "source_name": "Trend Micro MacOS Backdoor November 2020", "url": "https://www.trendmicro.com/en_us/research/20/k/new-macos-backdoor-connected-to-oceanlotus-surfaces.html"}, {"description": "Phil Stokes. (2020, December 2). APT32 Multi-stage macOS Trojan Innovates on Crimeware Scripting Technique. Retrieved September 13, 2021.", "source_name": "sentinelone apt32 macOS backdoor 2020", "url": "https://www.sentinelone.com/labs/apt32-multi-stage-macos-trojan-innovates-on-crimeware-scripting-technique/"}], "id": "relationship--4f9fef8b-1ceb-4a10-b6ea-ff2a9680154f", "modified": "2026-04-29T14:23:06.034Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--b00f90b6-c75c-4bfd-b813-ca9e6c9ebf29", "spec_version": "2.1", "target_ref": "attack-pattern--a9d4b653-6915-42af-98b2-5758c4ceee56", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20540', 0, 117, '09-mitre-attack', 'retrieved', '22BBAE53B7432D79CB8962F9A41F22C0F1BBC6E83FBCB07C4A6E8778E2ACC81A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
