VALUES ('doc-09-mitre-attack-p0-20551', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-09-26T16:22:41.856Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OSX_OCEANLOTUS.D](https://attack.mitre.org/software/S0352) has a variant that is packed with UPX.(Citation: ESET OceanLotus macOS April 2019)", "external_references": [{"description": "Dumont, R.. (2019, April 9). OceanLotus: macOS malware update. Retrieved April 15, 2019.", "source_name": "ESET OceanLotus macOS April 2019", "url": "https://www.welivesecurity.com/2019/04/09/oceanlotus-macos-malware-update/"}], "id": "relationship--79127e56-edbc-422b-9c32-72ce55f5ec04", "modified": "2026-04-29T14:23:06.090Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--b00f90b6-c75c-4bfd-b813-ca9e6c9ebf29", "spec_version": "2.1", "target_ref": "attack-pattern--deb98323-e13f-4b0c-8d94-175379069062", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20551', 0, 66, '09-mitre-attack', 'retrieved', '3A4E268435B76B735F3E2B6158A5C1127D092C527CD1341A6F57ADF08EDED30D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
