VALUES ('doc-09-mitre-attack-p0-20553', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-02T14:07:12.621Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OSX_OCEANLOTUS.D](https://attack.mitre.org/software/S0352) uses file naming conventions with associated executable locations to blend in with the macOS TimeMachine and OpenSSL services. Such as, naming a LaunchAgent plist file `com.apple.openssl.plist` which executes [OSX_OCEANLOTUS.D](https://attack.mitre.org/software/S0352) from the user''s `~/Library/OpenSSL/` folder upon user login.(Citation: Unit42 OceanLotus 2017)", "external_references": [{"description": "Erye Hernandez and Danny Tsechansky. (2017, June 22). The New and Improved macOS Backdoor from OceanLotus. Retrieved September 8, 2023.", "source_name": "Unit42 OceanLotus 2017", "url": "https://unit42.paloaltonetworks.com/unit42-new-improved-macos-backdoor-oceanlotus/"}], "id": "relationship--9e6bbb1a-95c6-4f51-9aff-6b424c731cfc", "modified": "2026-04-29T14:23:06.141Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--b00f90b6-c75c-4bfd-b813-ca9e6c9ebf29", "spec_version": "2.1", "target_ref": "attack-pattern--7bdca9d5-d500-4d7d-8c52-5fd47baf4c0c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20553', 0, 98, '09-mitre-attack', 'retrieved', '5223575EBA769F627E926EE4FF7AAE2296A77B94E7FA1E5AE77B17FFE36A0A0E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
