VALUES ('doc-09-mitre-attack-p0-20605', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Some variants of [Cherry Picker](https://attack.mitre.org/software/S0107) use AppInit_DLLs to achieve persistence by creating the following Registry key: HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Windows \"AppInit_DLLs\"=\"pserver32.dll\" (Citation: Trustwave Cherry Picker)", "external_references": [{"description": "Merritt, E.. (2015, November 16). Shining the Spotlight on Cherry Picker PoS Malware. Retrieved April 20, 2016.", "source_name": "Trustwave Cherry Picker", "url": "https://www.trustwave.com/Resources/SpiderLabs-Blog/Shining-the-Spotlight-on-Cherry-Picker-PoS-Malware/"}], "id": "relationship--cb4af413-9bd7-4f1a-a693-57d11ffccbf5", "modified": "2026-04-29T14:23:06.203Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--b2203c59-4089-4ee4-bfe1-28fa25f0dbfe", "spec_version": "2.1", "target_ref": "attack-pattern--cc89ecbd-3d33-4a41-bcca-001e702d18fd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20605', 0, 77, '09-mitre-attack', 'retrieved', '81718D5EAEDD228E21213B6DAA04C7E206F7F5D525B343F85B4986347C54924C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
