VALUES ('doc-09-mitre-attack-p0-20607', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-18T20:23:02.334Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SUPERNOVA](https://attack.mitre.org/software/S0578) had to receive an HTTP GET request containing a specific set of parameters in order to execute.(Citation: Guidepoint SUPERNOVA Dec 2020)(Citation: Unit42 SUPERNOVA Dec 2020)", "external_references": [{"description": "Riley, W. (2020, December 1). SUPERNOVA SolarWinds .NET Webshell Analysis. Retrieved February 18, 2021.", "source_name": "Guidepoint SUPERNOVA Dec 2020", "url": "https://www.guidepointsecurity.com/supernova-solarwinds-net-webshell-analysis/"}, {"description": "Tennis, M. (2020, December 17). SUPERNOVA: A Novel .NET Webshell. Retrieved February 22, 2021.", "source_name": "Unit42 SUPERNOVA Dec 2020", "url": "https://unit42.paloaltonetworks.com/solarstorm-supernova/"}], "id": "relationship--072ce102-e907-455c-a707-cded0bb29216", "modified": "2026-04-29T14:23:05.913Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--b2b0b946-be0a-4a7f-9c32-a2e5211d1cd9", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20607', 0, 100, '09-mitre-attack', 'retrieved', 'DC4630C9BC15942DCB537907A24FE2305BC708A0C499EEA598D14ADC716584C1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
