VALUES ('doc-09-mitre-attack-p0-20620', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-11T21:23:29.635Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CaddyWiper](https://attack.mitre.org/software/S0693) can use `DsRoleGetPrimaryDomainInformation` to determine the role of the infected machine. [CaddyWiper](https://attack.mitre.org/software/S0693) can also halt execution if the compromised host is identified as a domain controller.(Citation: Cisco CaddyWiper March 2022)(Citation: Malwarebytes IssacWiper CaddyWiper March 2022 )", "external_references": [{"description": "Malhotra, A. (2022, March 15). Threat Advisory: CaddyWiper. Retrieved March 23, 2022.", "source_name": "Cisco CaddyWiper March 2022", "url": "https://blog.talosintelligence.com/2022/03/threat-advisory-caddywiper.html"}, {"description": "Threat Intelligence Team. (2022, March 18). Double header: IsaacWiper and CaddyWiper . Retrieved April 11, 2022.", "source_name": "Malwarebytes IssacWiper CaddyWiper March 2022 ", "url": "https://blog.malwarebytes.com/threat-intelligence/2022/03/double-header-isaacwiper-and-caddywiper/"}], "id": "relationship--6b7ef377-d7c3-47ca-9707-03d4ccaf5adb", "modified": "2026-04-29T14:23:06.071Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--b30d999d-64e0-4e35-9856-884e4b83d611", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20620', 0, 113, '09-mitre-attack', 'retrieved', '995612A62E920786609D00C5DC04335CE510D74714FCDEE2682DA005292F0AE7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
