VALUES ('doc-09-mitre-attack-p0-20626', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-23T20:35:57.941Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[CaddyWiper](https://attack.mitre.org/software/S0693) has the ability to destroy information about a physical drive''s partitions including the MBR, GPT, and partition entries.(Citation: ESET CaddyWiper March 2022)(Citation: Cisco CaddyWiper March 2022)", "external_references": [{"description": "ESET. (2022, March 15). CaddyWiper: New wiper malware discovered in Ukraine. Retrieved March 23, 2022.", "source_name": "ESET CaddyWiper March 2022", "url": "https://www.welivesecurity.com/2022/03/15/caddywiper-new-wiper-malware-discovered-ukraine"}, {"description": "Malhotra, A. (2022, March 15). Threat Advisory: CaddyWiper. Retrieved March 23, 2022.", "source_name": "Cisco CaddyWiper March 2022", "url": "https://blog.talosintelligence.com/2022/03/threat-advisory-caddywiper.html"}], "id": "relationship--f9bcef0c-01a5-4fd8-a6f1-8423b5e98e52", "modified": "2026-04-29T14:23:06.264Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--b30d999d-64e0-4e35-9856-884e4b83d611", "spec_version": "2.1", "target_ref": "attack-pattern--0af0ca99-357d-4ba1-805f-674fdfb7bef9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20626', 0, 100, '09-mitre-attack', 'retrieved', 'B6D2568BA203856D82A54CCC4F4C1DB4F6EE2589C91EF590572B117407051B3A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
