VALUES ('doc-09-mitre-attack-p0-20628', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-07T19:33:27.021Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cyclops Blink](https://attack.mitre.org/software/S0687) can encrypt C2 messages with AES-256-CBC sent underneath TLS. OpenSSL library functions are also used to encrypt each message using a randomly generated key and IV, which are then encrypted using a hard-coded RSA public key.(Citation: NCSC Cyclops Blink February 2022)", "external_references": [{"description": "NCSC. (2022, February 23). Cyclops Blink Malware Analysis Report. Retrieved March 3, 2022.", "source_name": "NCSC Cyclops Blink February 2022", "url": "https://www.ncsc.gov.uk/files/Cyclops-Blink-Malware-Analysis-Report.pdf"}], "id": "relationship--0766fe91-a8d9-42bd-8023-f2134b280211", "modified": "2026-04-29T14:23:05.913Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--b350b47f-88fe-4921-8538-6d9c59bac84e", "spec_version": "2.1", "target_ref": "attack-pattern--bf176076-b789-408e-8cba-7275e81c0ada", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20628', 0, 95, '09-mitre-attack', 'retrieved', 'AB32E49760AC492E7666EFD51E92577D2CD0277C9BE5F11DE92E3CA3D08B0B1A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
