VALUES ('doc-09-mitre-attack-p0-20630', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-03T16:46:03.873Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cyclops Blink](https://attack.mitre.org/software/S0687) can rename its running process to [kworker:0/1] to masquerade as a Linux kernel thread. [Cyclops Blink](https://attack.mitre.org/software/S0687) has also named RC scripts used for persistence after WatchGuard artifacts.(Citation: NCSC Cyclops Blink February 2022)", "external_references": [{"description": "NCSC. (2022, February 23). Cyclops Blink Malware Analysis Report. Retrieved March 3, 2022.", "source_name": "NCSC Cyclops Blink February 2022", "url": "https://www.ncsc.gov.uk/files/Cyclops-Blink-Malware-Analysis-Report.pdf"}], "id": "relationship--1ad60707-d84f-4768-9013-6b499de49c40", "modified": "2026-04-29T14:23:05.941Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--b350b47f-88fe-4921-8538-6d9c59bac84e", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20630', 0, 86, '09-mitre-attack', 'retrieved', '48A4324B4AA86E172D01F7652C506792189840C90341B80D479B6D91CD26D33A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
