VALUES ('doc-09-mitre-attack-p0-20631', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-07T19:16:28.185Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cyclops Blink](https://attack.mitre.org/software/S0687) has the ability to query device information.(Citation: NCSC Cyclops Blink February 2022)", "external_references": [{"description": "NCSC. (2022, February 23). Cyclops Blink Malware Analysis Report. Retrieved March 3, 2022.", "source_name": "NCSC Cyclops Blink February 2022", "url": "https://www.ncsc.gov.uk/files/Cyclops-Blink-Malware-Analysis-Report.pdf"}], "id": "relationship--350776c3-9234-4c8f-adff-9b36778e90c4", "modified": "2026-04-29T14:23:05.990Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--b350b47f-88fe-4921-8538-6d9c59bac84e", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20631', 0, 66, '09-mitre-attack', 'retrieved', 'F44A765523E64E57AFF793B93FF5D28C9ABFB1763263309D5BB6E2D049165A27', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
