VALUES ('doc-09-mitre-attack-p0-20632', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-03T16:36:21.289Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cyclops Blink](https://attack.mitre.org/software/S0687) has maintained persistence by patching legitimate device firmware when it is downloaded, including that of WatchGuard devices.(Citation: NCSC Cyclops Blink February 2022)", "external_references": [{"description": "NCSC. (2022, February 23). Cyclops Blink Malware Analysis Report. Retrieved March 3, 2022.", "source_name": "NCSC Cyclops Blink February 2022", "url": "https://www.ncsc.gov.uk/files/Cyclops-Blink-Malware-Analysis-Report.pdf"}], "id": "relationship--4b2668bf-31ee-4bee-a624-ab526124623b", "modified": "2026-04-29T14:23:06.028Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--b350b47f-88fe-4921-8538-6d9c59bac84e", "spec_version": "2.1", "target_ref": "attack-pattern--791481f8-e96a-41be-b089-a088763083d4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20632', 0, 76, '09-mitre-attack', 'retrieved', 'C846E6194375575C119631B64AF63447B7D0D32153379B963F1A5A97EF4BD4C4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
