VALUES ('doc-09-mitre-attack-p0-20730', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-06T15:26:38.970Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PLEAD](https://attack.mitre.org/software/S0435) can harvest saved credentials from browsers such as Google Chrome, Microsoft Internet Explorer, and Mozilla Firefox.(Citation: TrendMicro BlackTech June 2017)(Citation: ESET PLEAD Malware July 2018)", "external_references": [{"description": "Bermejo, L., et al. (2017, June 22). Following the Trail of BlackTech’s Cyber Espionage Campaigns. Retrieved May 5, 2020.", "source_name": "TrendMicro BlackTech June 2017", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/following-trail-blacktech-cyber-espionage-campaigns/"}, {"description": "Cherepanov, A.. (2018, July 9). Certificates stolen from Taiwanese tech‑companies misused in Plead malware campaign. Retrieved May 6, 2020.", "source_name": "ESET PLEAD Malware July 2018", "url": "https://www.welivesecurity.com/2018/07/09/certificates-stolen-taiwanese-tech-companies-plead-malware-campaign/"}], "id": "relationship--f1952dea-f9d6-421b-947e-502796e2c883", "modified": "2026-04-29T14:23:06.254Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--b57f419e-8b12-49d3-886b-145383725dcd", "spec_version": "2.1", "target_ref": "attack-pattern--58a3e6aa-4453-4cc8-a51f-4befe80b31a8", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20730', 0, 111, '09-mitre-attack', 'retrieved', 'F4CF37D0A155DBEEF76EAFCEDA4A36C7A70D32FAFF702DDBD87C0A3B56ED8764', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
