VALUES ('doc-09-mitre-attack-p0-20758', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T20:45:56.809Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[IPsec Helper](https://attack.mitre.org/software/S1132) can delete various service traces related to persistent execution when commanded.(Citation: SentinelOne Agrius 2021)", "external_references": [{"description": "Amitai Ben & Shushan Ehrlich. (2021, May). From Wiper to Ransomware: The Evolution of Agrius. Retrieved May 21, 2024.", "source_name": "SentinelOne Agrius 2021", "url": "https://assets.sentinelone.com/sentinellabs/evol-agrius"}], "id": "relationship--5aa5a69f-967b-4b4a-8d4a-f347bff547f2", "modified": "2026-04-29T14:23:06.049Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--b5dc19b7-588d-403b-848d-c868bd61ffa1", "spec_version": "2.1", "target_ref": "attack-pattern--d2c4e5ea-dbdf-4113-805a-b1e2a337fb33", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20758', 0, 72, '09-mitre-attack', 'retrieved', 'A77ED47E8E15D1E64006FD3D30478F764E4B6B3F3EDF753B38BD9093FBB9C2E6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
