VALUES ('doc-09-mitre-attack-p0-20807', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-14T12:59:05.105Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TRAILBLAZE](https://attack.mitre.org/software/S9012) has the ability to delete temporary files and contents in specified directories to cover its tracks.(Citation: Google UNC5221 Ivanti April 2025)(Citation: Picus Security UNC5221 Ivanti May 2025)", "external_references": [{"description": "John Wolfram, Michael Edie, Jacob Thompson, Matt Lin, Josh Murchie. (2025, April 3). Suspected China-Nexus Threat Actor Actively Exploiting Critical Ivanti Connect Secure Vulnerability (CVE-2025-22457). Retrieved April 13, 2026.", "source_name": "Google UNC5221 Ivanti April 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/china-nexus-exploiting-critical-ivanti-vulnerability"}, {"description": "Sila Ozeren Hacioglu. (2025, May 5). UNC5221’s Latest Exploit: Weaponizing CVE-2025-22457 in Ivanti Connect Secure. Retrieved April 13, 2026.", "source_name": "Picus Security UNC5221 Ivanti May 2025", "url": "https://www.picussecurity.com/resource/blog/unc5221-cve-2025-22457-ivanti-connect-secure"}], "id": "relationship--6f2fca5b-79b5-4fb4-9f5f-e786ce9b6e9c", "modified": "2026-04-29T14:23:06.077Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--b82b9e25-e37b-4f7c-b1f0-2c2eea4f4be9", "spec_version": "2.1", "target_ref": "attack-pattern--d63a3fb8-9452-4e9d-a60a-54be68d5998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20807', 0, 125, '09-mitre-attack', 'retrieved', '17A3A804C7A845BE933FE6E53E12F0CD47A65A6B0E5F5D7C9C51A62B58F0040B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_ve