VALUES ('doc-09-mitre-attack-p0-20810', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-02T12:58:09.722Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LoJax](https://attack.mitre.org/software/S0397) has modified the Registry key ‘HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Control\\Session Manager\\BootExecute’ from ‘autocheck autochk *’ to ‘autocheck autoche *’ .(Citation: ESET LoJax Sept 2018)", "external_references": [{"description": "ESET. (2018, September). LOJAX First UEFI rootkit found in the wild, courtesy of the Sednit group. Retrieved July 2, 2019.", "source_name": "ESET LoJax Sept 2018", "url": "https://www.welivesecurity.com/wp-content/uploads/2018/09/ESET-LoJax.pdf"}], "id": "relationship--1f5c6a39-aa0b-469e-aabe-67e4d237b213", "modified": "2026-04-29T14:23:05.947Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--b865dded-0553-4962-a44b-6fe7863effed", "spec_version": "2.1", "target_ref": "attack-pattern--57340c81-c025-4189-8fa0-fc7ede51bae4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20810', 0, 79, '09-mitre-attack', 'retrieved', '1964E84D5A1F0F1236368958563DEE4F301ADE80702D144C89919DB4D5331AF3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
