VALUES ('doc-09-mitre-attack-p0-20902', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-23T14:20:48.632Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GoldenSpy](https://attack.mitre.org/software/S0493) has included a program \"ExeProtector\", which monitors for the existence of [GoldenSpy](https://attack.mitre.org/software/S0493) on the infected system and redownloads if necessary.(Citation: Trustwave GoldenSpy June 2020)\t", "external_references": [{"description": "Trustwave SpiderLabs. (2020, June 25). The Golden Tax Department and Emergence of GoldenSpy Malware. Retrieved July 23, 2020.", "source_name": "Trustwave GoldenSpy June 2020", "url": "https://www.trustwave.com/en-us/resources/library/documents/the-golden-tax-department-and-the-emergence-of-goldenspy-malware/"}], "id": "relationship--7f499274-44b7-4415-a8e8-6b2134a7873e", "modified": "2026-04-29T14:23:06.100Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--b9704a7d-feef-4af9-8898-5280f1686326", "spec_version": "2.1", "target_ref": "attack-pattern--7bc57495-ea59-4380-be31-a64af124ef18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20902', 0, 81, '09-mitre-attack', 'retrieved', '883FAABBCC727E48E0696F9300D29FC847423FB7D5870153748696010E7BD973', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
