VALUES ('doc-09-mitre-attack-p0-20931', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-24T20:25:01.289Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ramsay](https://attack.mitre.org/software/S0458) can take screenshots every 30 seconds as well as when an external removable storage device is connected.(Citation: Antiy CERT Ramsay April 2020)", "external_references": [{"description": "Antiy CERT. (2020, April 20). Analysis of Ramsay components of Darkhotel''s infiltration and isolation network. Retrieved March 24, 2021.", "source_name": "Antiy CERT Ramsay April 2020", "url": "https://www.programmersought.com/article/62493896999/"}], "id": "relationship--145d2112-b679-4d72-b484-7524f944e128", "modified": "2026-04-29T14:23:05.932Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--ba09b86c-1c40-4ff1-bda0-0d8c4ca35997", "spec_version": "2.1", "target_ref": "attack-pattern--0259baeb-9f63-4c69-bf10-eb038c390688", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20931', 0, 81, '09-mitre-attack', 'retrieved', 'B5032A3535FF311C476D80347F298AEBB0250E0882DBE885C5E378B8F72BCEE3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
