VALUES ('doc-09-mitre-attack-p0-20932', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-24T20:25:01.355Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ramsay](https://attack.mitre.org/software/S0458) can use [ipconfig](https://attack.mitre.org/software/S0100) and [Arp](https://attack.mitre.org/software/S0099) to collect network configuration information, including routing information and ARP tables.(Citation: Antiy CERT Ramsay April 2020)", "external_references": [{"description": "Antiy CERT. (2020, April 20). Analysis of Ramsay components of Darkhotel''s infiltration and isolation network. Retrieved March 24, 2021.", "source_name": "Antiy CERT Ramsay April 2020", "url": "https://www.programmersought.com/article/62493896999/"}], "id": "relationship--1884ba87-a1c8-496b-9517-abb379911166", "modified": "2026-04-29T14:23:05.938Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--ba09b86c-1c40-4ff1-bda0-0d8c4ca35997", "spec_version": "2.1", "target_ref": "attack-pattern--707399d6-ab3e-4963-9315-d9d3818cd6a0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20932', 0, 80, '09-mitre-attack', 'retrieved', '3FD3EBF6FB680F5842176DC411F032FE8297DE7A05B917B36CBBAC575C35F476', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
