VALUES ('doc-09-mitre-attack-p0-20933', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-28T16:38:03.762Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ramsay](https://attack.mitre.org/software/S0458) can use Windows API functions such as WriteFile , CloseHandle , and GetCurrentHwProfile during its collection and file storage operations. [Ramsay](https://attack.mitre.org/software/S0458) can execute its embedded components via CreateProcessA and ShellExecute .(Citation: Eset Ramsay May 2020)", "external_references": [{"description": "Sanmillan, I.. (2020, May 13). Ramsay: A cyber‑espionage toolkit tailored for air‑gapped networks. Retrieved May 27, 2020.", "source_name": "Eset Ramsay May 2020", "url": "https://www.welivesecurity.com/2020/05/13/ramsay-cyberespionage-toolkit-airgapped-networks/"}], "id": "relationship--239eb918-b9e0-499c-9934-96382fa782a0", "modified": "2026-04-29T14:23:05.954Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--ba09b86c-1c40-4ff1-bda0-0d8c4ca35997", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20933', 0, 91, '09-mitre-attack', 'retrieved', 'F4A205A53CD87EB886B5EF46C2C3CD719D1EB550B9D50560096F64C2ED9B14D8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
