VALUES ('doc-09-mitre-attack-p0-20975', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-06T18:48:52.848Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Neo-reGeorg](https://attack.mitre.org/software/S1189) can be installed on compromised web servers to tunnel C2 connections.(Citation: GitHub Neo-reGeorg 2019)(Citation: Mandiant-Sandworm-Ukraine-2022)", "external_references": [{"description": "Ken Proska, John Wolfram, Jared Wilson, Dan Black, Keith Lunden, Daniel Kapellmann Zafra, Nathan Brubaker, Tyler Mclellan, Chris Sistrunk. (2023, November 9). Sandworm Disrupts Power in Ukraine Using a Novel Attack Against Operational Technology. Retrieved March 28, 2024.", "source_name": "Mandiant-Sandworm-Ukraine-2022", "url": "https://www.mandiant.com/resources/blog/sandworm-disrupts-power-ukraine-operational-technology"}, {"description": "L-Codes. (2019). Neo-reGeorg. Retrieved December 4, 2024.", "source_name": "GitHub Neo-reGeorg 2019", "url": "https://github.com/L-codes/Neo-reGeorg/blob/master/README-en.md"}], "id": "relationship--7fd41982-17d3-4f09-812b-8024c3b5f500", "modified": "2026-04-29T14:23:06.100Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--bae6edd1-eb36-4581-ba7e-6cbfe0e24eac", "spec_version": "2.1", "target_ref": "attack-pattern--5d0d3609-d06d-49e1-b9c9-b544e0c618cb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-20975', 0, 103, '09-mitre-attack', 'retrieved', 'F8A4AECC7B44AE562BB1D6D339B9562DFD6CDE1EDAF8701CDA3E2CEB368D0C2B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
