VALUES ('doc-09-mitre-attack-p0-21025', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-11T18:03:50.288Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FRAMESTING](https://attack.mitre.org/software/S1120) can retrieve C2 commands from values stored in the `DSID` cookie from the current HTTP request or from decompressed zlib data within the request''s `POST` data.(Citation: Mandiant Cutting Edge Part 2 January 2024)", "external_references": [{"description": "Lin, M. et al. (2024, January 31). Cutting Edge, Part 2: Investigating Ivanti Connect Secure VPN Zero-Day Exploitation. Retrieved February 27, 2024.", "source_name": "Mandiant Cutting Edge Part 2 January 2024", "url": "https://www.mandiant.com/resources/blog/investigating-ivanti-zero-day-exploitation"}], "id": "relationship--323269a9-56d0-45d5-8010-652657841f0e", "modified": "2026-04-29T14:23:05.983Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--bcaae558-9697-47a2-9ec7-c75000ddf58c", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21025', 0, 97, '09-mitre-attack', 'retrieved', '6A023865E8D0A45AF17FD8EC6624D7760D0B7787B3898550AF88C03B687F4741', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
