VALUES ('doc-09-mitre-attack-p0-21031', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-30T19:45:04.381Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HARDRAIN](https://attack.mitre.org/software/S0246) binds and listens on port 443 with a FakeTLS method.(Citation: US-CERT HARDRAIN March 2018)", "external_references": [{"description": "US-CERT. (2018, February 05). Malware Analysis Report (MAR) - 10135536-F. Retrieved June 11, 2018.", "source_name": "US-CERT HARDRAIN March 2018", "url": "https://www.us-cert.gov/sites/default/files/publications/MAR-10135536-F.pdf"}], "id": "relationship--53e123a8-0794-4bec-b71b-3c4b4a94057f", "modified": "2026-04-29T14:23:06.040Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--bd0536d7-b081-43ae-a773-cfb057c5b988", "spec_version": "2.1", "target_ref": "attack-pattern--b18eae87-b469-4e14-b454-b171b416bc18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21031', 0, 67, '09-mitre-attack', 'retrieved', 'F4031EA38B47341AC37379844798D22B43A3EA656BBC40073323E67C1BBF9820', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
