VALUES ('doc-09-mitre-attack-p0-21032', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[HARDRAIN](https://attack.mitre.org/software/S0246) uses the command cmd.exe /c netsh firewall add portopening TCP 443 \"adp\" and makes the victim machine function as a proxy server.(Citation: US-CERT HARDRAIN March 2018)", "external_references": [{"description": "US-CERT. (2018, February 05). Malware Analysis Report (MAR) - 10135536-F. Retrieved June 11, 2018.", "source_name": "US-CERT HARDRAIN March 2018", "url": "https://www.us-cert.gov/sites/default/files/publications/MAR-10135536-F.pdf"}], "id": "relationship--74bb0ae9-589c-4479-9bd5-b9a71a20e82d", "modified": "2026-04-29T14:23:06.085Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--bd0536d7-b081-43ae-a773-cfb057c5b988", "spec_version": "2.1", "target_ref": "attack-pattern--731f4f55-b6d0-41d1-a7a9-072a66389aea", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21032', 0, 79, '09-mitre-attack', 'retrieved', '60988F19D7B6097176C35C53E20F446C4F19477B593157BAA041E576F5F35FD1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
