VALUES ('doc-09-mitre-attack-p0-21046', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-27T15:20:50.519Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pillowmint](https://attack.mitre.org/software/S0517) has modified the Registry key HKLM\\SOFTWARE\\Microsoft\\DRM to store a malicious payload.(Citation: Trustwave Pillowmint June 2020)", "external_references": [{"description": "Trustwave SpiderLabs. (2020, June 22). Pillowmint: FIN7’s Monkey Thief . Retrieved July 27, 2020.", "source_name": "Trustwave Pillowmint June 2020", "url": "https://www.trustwave.com/en-us/resources/blogs/spiderlabs-blog/pillowmint-fin7s-monkey-thief/"}], "id": "relationship--332ce4cd-311a-457f-ae10-6d8e3ef7bc77", "modified": "2026-04-29T14:23:05.986Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--bd7a9e13-69fa-4243-a5e5-04326a63f9f2", "spec_version": "2.1", "target_ref": "attack-pattern--57340c81-c025-4189-8fa0-fc7ede51bae4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21046', 0, 68, '09-mitre-attack', 'retrieved', '3DFFF81B00DAF3749AA570D063C4D7FAA301E8EBF0F896E9D48396E123C49E31', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
