VALUES ('doc-09-mitre-attack-p0-21047', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-09-23T20:30:55.982Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Pillowmint](https://attack.mitre.org/software/S0517) has used shellcode which reads code stored in the registry keys \\REGISTRY\\SOFTWARE\\Microsoft\\DRM using the native Windows API as well as read HKEY_LOCAL_MACHINE\\System\\CurrentControlSet\\Services\\Tcpip\\Parameters\\Interfaces as part of its C2.(Citation: Trustwave Pillowmint June 2020)\t", "external_references": [{"description": "Trustwave SpiderLabs. (2020, June 22). Pillowmint: FIN7’s Monkey Thief . Retrieved July 27, 2020.", "source_name": "Trustwave Pillowmint June 2020", "url": "https://www.trustwave.com/en-us/resources/blogs/spiderlabs-blog/pillowmint-fin7s-monkey-thief/"}], "id": "relationship--3454bb10-fad3-48b6-b20a-81cb45e7bbc1", "modified": "2026-04-29T14:23:05.989Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--bd7a9e13-69fa-4243-a5e5-04326a63f9f2", "spec_version": "2.1", "target_ref": "attack-pattern--c32f7008-9fea-41f7-8366-5eb9b74bd896", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21047', 0, 84, '09-mitre-attack', 'retrieved', '0A9807D3F18B070D7BD53CE31DE511DB153D47E913AE53737D4D528D4C2E06C8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
