VALUES ('doc-09-mitre-attack-p0-21087', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-18T21:47:07.938Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MacMa](https://attack.mitre.org/software/S1016) has stored collected files locally before exfiltration.(Citation: Objective-See MacMa Nov 2021)", "external_references": [{"description": "Wardle, P. (2021, November 11). OSX.CDDS (OSX.MacMa). Retrieved June 30, 2022.", "source_name": "Objective-See MacMa Nov 2021", "url": "https://objective-see.org/blog/blog_0x69.html"}], "id": "relationship--44a77efc-9215-4e5a-a246-ac9669dc52a4", "modified": "2026-04-29T14:23:06.019Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--bdee9574-7479-4073-a7dc-e86d8acd073a", "spec_version": "2.1", "target_ref": "attack-pattern--1c34f7aa-9341-4a48-bfab-af22e51aca6c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21087', 0, 61, '09-mitre-attack', 'retrieved', '2ED1FA4535A9C92F002A465973DE898016EFFAA1A757DA3D8E9C2055B17A64DB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
