VALUES ('doc-09-mitre-attack-p0-21099', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-30T20:39:33.887Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MacMa](https://attack.mitre.org/software/S1016) can use Core Graphics Event Taps to intercept user keystrokes from any text input field and saves them to text files. Text input fields include Spotlight, Finder, Safari, Mail, Messages, and other apps that have text fields for passwords.(Citation: Objective-See MacMa Nov 2021)(Citation: SentinelOne MacMa Nov 2021)", "external_references": [{"description": "Stokes, P. (2021, November 15). Infect If Needed | A Deeper Dive Into Targeted Backdoor macOS.Macma. Retrieved June 30, 2022.", "source_name": "SentinelOne MacMa Nov 2021", "url": "https://www.sentinelone.com/labs/infect-if-needed-a-deeper-dive-into-targeted-backdoor-macos-macma/"}, {"description": "Wardle, P. (2021, November 11). OSX.CDDS (OSX.MacMa). Retrieved June 30, 2022.", "source_name": "Objective-See MacMa Nov 2021", "url": "https://objective-see.org/blog/blog_0x69.html"}], "id": "relationship--b5a39593-27ad-44dc-99f9-fcadc6d464ed", "modified": "2026-04-29T14:23:06.173Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--bdee9574-7479-4073-a7dc-e86d8acd073a", "spec_version": "2.1", "target_ref": "attack-pattern--09a60ea3-a8d1-4ae5-976e-5783248b72a4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21099', 0, 125, '09-mitre-attack', 'retrieved', '783E9F9530BE870F0EF3B2B8A0C05A5C2555AFA6566DF714DCD6446A635F695F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
