VALUES ('doc-09-mitre-attack-p0-21115', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-26T17:34:15.597Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [FunnyDream](https://attack.mitre.org/software/S1044) FilepakMonitor component can inject into the Bka.exe process using the `VirtualAllocEx`, `WriteProcessMemory` and `CreateRemoteThread` APIs to load the DLL component.(Citation: Bitdefender FunnyDream Campaign November 2020)", "external_references": [{"description": "Vrabie, V. (2020, November). Dissecting a Chinese APT Targeting South Eastern Asian Government Institutions. Retrieved September 19, 2022.", "source_name": "Bitdefender FunnyDream Campaign November 2020", "url": "https://www.bitdefender.com/files/News/CaseStudies/study/379/Bitdefender-Whitepaper-Chinese-APT.pdf"}], "id": "relationship--44a97cbb-ce03-43ee-959e-c582e64372a2", "modified": "2026-04-29T14:23:06.019Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--be25c1c0-1590-4219-a3d5-6f31799d1d1b", "spec_version": "2.1", "target_ref": "attack-pattern--f4599aa0-4f85-4a32-80ea-fc39dc965945", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21115', 0, 84, '09-mitre-attack', 'retrieved', 'D8E7DFA68E269833BA1D66F43796FFC2D1A79781F0D5D20A3932332D505D483B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
