VALUES ('doc-09-mitre-attack-p0-21156', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-08T18:07:21.715Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ROADSWEEP](https://attack.mitre.org/software/S1150) requires four command line arguments to execute correctly, otherwise it will produce a message box and halt execution.(Citation: Mandiant ROADSWEEP August 2022)(Citation: CISA Iran Albanian Attacks September 2022)(Citation: Microsoft Albanian Government Attacks September 2022)\n", "external_references": [{"description": "CISA. (2022, September 23). AA22-264A Iranian State Actors Conduct Cyber Operations Against the Government of Albania. Retrieved August 6, 2024.", "source_name": "CISA Iran Albanian Attacks September 2022", "url": "https://www.cisa.gov/news-events/cybersecurity-advisories/aa22-264a"}, {"description": "Jenkins, L. at al. (2022, August 4). ROADSWEEP Ransomware - Likely Iranian Threat Actor Conducts Politically Motivated Disruptive Activity Against Albanian Government Organizations. Retrieved August 6, 2024.", "source_name": "Mandiant ROADSWEEP August 2022", "url": "https://cloud.google.com/blog/topics/threat-intelligence/likely-iranian-threat-actor-conducts-politically-motivated-disruptive-activity-against/"}, {"description": "MSTIC. (2022, September 8). Microsoft investigates Iranian attacks against the Albanian government. Retrieved August 6, 2024.", "source_name": "Microsoft Albanian Government Attacks September 2022", "url": "https://www.microsoft.com/en-us/security/blog/2022/09/08/microsoft-investigates-iranian-attacks-against-the-albanian-government/"}], "id": "relationship--c29450bf-20a4-47f8-8ef9-7c6559cfad75", "modified": "2026-04-29T14:23:06.191Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--be471c69-12d5-4bcc-9dad-3d42c3dbca4b", "spec_version": "2.1", "target_ref": "attack-