VALUES ('doc-09-mitre-attack-p0-21158', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-08T18:37:51.506Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ROADSWEEP](https://attack.mitre.org/software/S1150) has the ability to disable `SystemRestore` and Volume Shadow Copies.(Citation: Mandiant ROADSWEEP August 2022)(Citation: CISA Iran Albanian Attacks September 2022)", "external_references": [{"description": "CISA. (2022, September 23). AA22-264A Iranian State Actors Conduct Cyber Operations Against the Government of Albania. Retrieved August 6, 2024.", "source_name": "CISA Iran Albanian Attacks September 2022", "url": "https://www.cisa.gov/news-events/cybersecurity-advisories/aa22-264a"}, {"description": "Jenkins, L. at al. (2022, August 4). ROADSWEEP Ransomware - Likely Iranian Threat Actor Conducts Politically Motivated Disruptive Activity Against Albanian Government Organizations. Retrieved August 6, 2024.", "source_name": "Mandiant ROADSWEEP August 2022", "url": "https://cloud.google.com/blog/topics/threat-intelligence/likely-iranian-threat-actor-conducts-politically-motivated-disruptive-activity-against/"}], "id": "relationship--f5d844e2-b442-4422-9880-e648ee387d67", "modified": "2026-04-29T14:23:06.259Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--be471c69-12d5-4bcc-9dad-3d42c3dbca4b", "spec_version": "2.1", "target_ref": "attack-pattern--f5d8eed6-48a9-4cdf-a3d7-d1ffa99c3d2a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21158', 0, 116, '09-mitre-attack', 'retrieved', '4ECDC887FDD0B8B5866D01C250E335EAAFD5406A19BEB8705A56AB8EDC5453D7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_typ