VALUES ('doc-09-mitre-attack-p0-21159', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-08T18:15:48.035Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ROADSWEEP](https://attack.mitre.org/software/S1150) can open cmd.exe to enable command execution.(Citation: Mandiant ROADSWEEP August 2022)(Citation: Microsoft Albanian Government Attacks September 2022)", "external_references": [{"description": "Jenkins, L. at al. (2022, August 4). ROADSWEEP Ransomware - Likely Iranian Threat Actor Conducts Politically Motivated Disruptive Activity Against Albanian Government Organizations. Retrieved August 6, 2024.", "source_name": "Mandiant ROADSWEEP August 2022", "url": "https://cloud.google.com/blog/topics/threat-intelligence/likely-iranian-threat-actor-conducts-politically-motivated-disruptive-activity-against/"}, {"description": "MSTIC. (2022, September 8). Microsoft investigates Iranian attacks against the Albanian government. Retrieved August 6, 2024.", "source_name": "Microsoft Albanian Government Attacks September 2022", "url": "https://www.microsoft.com/en-us/security/blog/2022/09/08/microsoft-investigates-iranian-attacks-against-the-albanian-government/"}], "id": "relationship--fa2bb401-2ab0-4971-948b-7faf58394399", "modified": "2026-04-29T14:23:06.265Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--be471c69-12d5-4bcc-9dad-3d42c3dbca4b", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21159', 0, 109, '09-mitre-attack', 'retrieved', '0CEA9564FDFF8C86D64A0CB9144C296180D92956EFDD71D06DC0A45181150964', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "cor