VALUES ('doc-09-mitre-attack-p0-21161', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-13T20:16:23.615Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SUNSPOT](https://attack.mitre.org/software/S0562) modified its security token to grants itself debugging privileges by adding SeDebugPrivilege .(Citation: CrowdStrike SUNSPOT Implant January 2021)", "external_references": [{"description": "CrowdStrike Intelligence Team. (2021, January 11). SUNSPOT: An Implant in the Build Process. Retrieved January 11, 2021.", "source_name": "CrowdStrike SUNSPOT Implant January 2021", "url": "https://www.crowdstrike.com/blog/sunspot-malware-technical-analysis/"}], "id": "relationship--339e74c4-5e3a-4272-966f-f5542d255d0a", "modified": "2026-04-29T14:23:05.987Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--bf48e7f8-752c-4ce8-bf8f-748edacd8fa6", "spec_version": "2.1", "target_ref": "attack-pattern--dcaa092b-7de9-4a21-977f-7fcb77e89c48", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21161', 0, 75, '09-mitre-attack', 'retrieved', 'C5B8A55AB501000A4F844B6369C49AB5CF5294A7D60D31F3ECEABB808DC7B3E0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
