VALUES ('doc-09-mitre-attack-p0-21167', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-13T21:09:53.217Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SUNSPOT](https://attack.mitre.org/software/S0562) malware was designed and used to insert [SUNBURST](https://attack.mitre.org/software/S0559) into software builds of the SolarWinds Orion IT management product.(Citation: CrowdStrike SUNSPOT Implant January 2021)", "external_references": [{"description": "CrowdStrike Intelligence Team. (2021, January 11). SUNSPOT: An Implant in the Build Process. Retrieved January 11, 2021.", "source_name": "CrowdStrike SUNSPOT Implant January 2021", "url": "https://www.crowdstrike.com/blog/sunspot-malware-technical-analysis/"}], "id": "relationship--84c6ce73-83b4-43f1-aeae-4b7e2f8b4d34", "modified": "2026-04-29T14:23:06.107Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--bf48e7f8-752c-4ce8-bf8f-748edacd8fa6", "spec_version": "2.1", "target_ref": "attack-pattern--bd369cd9-abb8-41ce-b5bb-fff23ee86c00", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21167', 0, 80, '09-mitre-attack', 'retrieved', 'D86C64E481F02D32D63DB217FBAA6FF99B505D05A9016D0A47305E295992458A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
