VALUES ('doc-09-mitre-attack-p0-21168', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-13T20:16:23.597Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SUNSPOT](https://attack.mitre.org/software/S0562) used Windows API functions such as MoveFileEx and NtQueryInformationProcess as part of the [SUNBURST](https://attack.mitre.org/software/S0559) injection process.(Citation: CrowdStrike SUNSPOT Implant January 2021) ", "external_references": [{"description": "CrowdStrike Intelligence Team. (2021, January 11). SUNSPOT: An Implant in the Build Process. Retrieved January 11, 2021.", "source_name": "CrowdStrike SUNSPOT Implant January 2021", "url": "https://www.crowdstrike.com/blog/sunspot-malware-technical-analysis/"}], "id": "relationship--9b59a1db-0b3d-4ce7-9cea-d91a71dd0a57", "modified": "2026-04-29T14:23:06.137Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--bf48e7f8-752c-4ce8-bf8f-748edacd8fa6", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21168', 0, 79, '09-mitre-attack', 'retrieved', 'FAD3159E5207A24D634D9B824CC1E7CB26250F255ADF90929C23ED5AC22EEFCA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
