VALUES ('doc-09-mitre-attack-p0-21170', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-13T18:23:50.496Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SUNSPOT](https://attack.mitre.org/software/S0562) decrypts [SUNBURST](https://attack.mitre.org/software/S0559), which was stored in AES128-CBC encrypted blobs.(Citation: CrowdStrike SUNSPOT Implant January 2021) ", "external_references": [{"description": "CrowdStrike Intelligence Team. (2021, January 11). SUNSPOT: An Implant in the Build Process. Retrieved January 11, 2021.", "source_name": "CrowdStrike SUNSPOT Implant January 2021", "url": "https://www.crowdstrike.com/blog/sunspot-malware-technical-analysis/"}], "id": "relationship--b8333924-1556-4c3f-b60f-105984e1f715", "modified": "2026-04-29T14:23:06.177Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--bf48e7f8-752c-4ce8-bf8f-748edacd8fa6", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21170', 0, 72, '09-mitre-attack', 'retrieved', '0AE4B3E386B6B1567890CCB81796A7C00A283556F8E47E4EDE46E6D094086667', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
