VALUES ('doc-09-mitre-attack-p0-21212', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-20T16:44:30.505Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SysUpdate](https://attack.mitre.org/software/S0663) can copy a script to the user owned `/usr/lib/systemd/system/` directory with a symlink mapped to a `root` owned directory, `/etc/ystem/system`, in the unit configuration file''s `ExecStart` directive to establish persistence and elevate privileges.(Citation: Lunghi Iron Tiger Linux)", "external_references": [{"description": "Daniel Lunghi. (2023, March 1). Iron Tiger’s SysUpdate Reappears, Adds Linux Targeting. Retrieved March 20, 2023.", "source_name": "Lunghi Iron Tiger Linux", "url": "https://www.trendmicro.com/en_us/research/23/c/iron-tiger-sysupdate-adds-linux-targeting.html"}], "id": "relationship--9a0137e5-82d0-4419-961a-9b0eb47b2d79", "modified": "2026-04-29T14:23:06.135Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--c009560a-f097-45a3-8f9f-78ec1440a783", "spec_version": "2.1", "target_ref": "attack-pattern--dfefe2ed-4389-4318-8762-f0272b350a1b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21212', 0, 92, '09-mitre-attack', 'retrieved', '431232F9D67A6A72CB6797E4654C54335FF68A5FF763DDE71EFDCCCD6683703D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
