VALUES ('doc-09-mitre-attack-p0-21275', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-19T15:27:05.568Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ANELLDR](https://attack.mitre.org/software/S9027) can decrypt encrypted payload data using AES-256-CBC and subsequently execute the payload in memory.(Citation: Trend Micro Earth Kasha Anel NOV 2024)\n", "external_references": [{"description": "Hiroaki, H. (2024, November 26). Guess Who’s Back - The Return of ANEL in the Recent Earth Kasha Spear-phishing Campaign in 2024. Retrieved April 17, 2026.", "source_name": "Trend Micro Earth Kasha Anel NOV 2024", "url": "https://www.trendmicro.com/en_us/research/24/k/return-of-anel-in-the-recent-earth-kasha-spearphishing-campaign.html"}], "id": "relationship--3f55cf61-8cbe-48ac-904f-299030d02dc3", "modified": "2026-04-29T14:23:06.011Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--c21edbd1-a0a4-4c3c-9b22-4a49634186c3", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21275', 0, 89, '09-mitre-attack', 'retrieved', 'C6CF68BD5A51FCF8529087A873F89FF8D9BEB95AF084A68E658FA10393CD1211', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
