VALUES ('doc-09-mitre-attack-p0-21276', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-19T15:25:04.064Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ANELLDR](https://attack.mitre.org/software/S9027) can update its encryption key to AES-256-CBC and re-encrypt its payload, overwriting the original payload file with the newly encrypted data.(Citation: Trend Micro Earth Kasha Anel NOV 2024)\n", "external_references": [{"description": "Hiroaki, H. (2024, November 26). Guess Who’s Back - The Return of ANEL in the Recent Earth Kasha Spear-phishing Campaign in 2024. Retrieved April 17, 2026.", "source_name": "Trend Micro Earth Kasha Anel NOV 2024", "url": "https://www.trendmicro.com/en_us/research/24/k/return-of-anel-in-the-recent-earth-kasha-spearphishing-campaign.html"}], "id": "relationship--6f8d8b9e-d41b-4e5d-9562-4e2c59aa7771", "modified": "2026-04-29T14:23:06.077Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--c21edbd1-a0a4-4c3c-9b22-4a49634186c3", "spec_version": "2.1", "target_ref": "attack-pattern--0d91b3c0-5e50-47c3-949a-2a796f04d144", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21276', 0, 96, '09-mitre-attack', 'retrieved', '65500EA5202A1ED17D3ACAD559C5D606E9577E6604B1C9E4F7906180BA23D7BF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
