VALUES ('doc-09-mitre-attack-p0-21293', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kwampirs](https://attack.mitre.org/software/S0236) downloads additional files from C2 servers.(Citation: Symantec Security Center Trojan.Kwampirs)", "external_references": [{"description": "Moench, B. and Aboud, E. (2016, August 23). Trojan.Kwampirs. Retrieved May 10, 2018.", "source_name": "Symantec Security Center Trojan.Kwampirs", "url": "https://www.symantec.com/security-center/writeup/2016-081923-2700-99"}], "id": "relationship--9b102737-2d47-4dd5-b4f2-2a323c506cfb", "modified": "2026-04-29T14:23:06.136Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--c2417bab-3189-4d4d-9d60-96de2cdaf0ab", "spec_version": "2.1", "target_ref": "attack-pattern--e6919abc-99f9-4c6c-95a5-14761e7b2add", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21293', 0, 62, '09-mitre-attack', 'retrieved', 'E42AECC0C31FFA1BB990C1125E275ABFA3F0D5E5979463BDFDEC6BDA8F32AF1C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
