VALUES ('doc-09-mitre-attack-p0-21298', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kwampirs](https://attack.mitre.org/software/S0236) collects a list of active and listening connections by using the command netstat -nao as well as a list of available network mappings with net use .(Citation: Symantec Orangeworm April 2018)", "external_references": [{"description": "Symantec Security Response Attack Investigation Team. (2018, April 23). New Orangeworm attack group targets the healthcare sector in the U.S., Europe, and Asia. Retrieved May 8, 2018.", "source_name": "Symantec Orangeworm April 2018", "url": "https://www.symantec.com/blogs/threat-intelligence/orangeworm-targets-healthcare-us-europe-asia"}], "id": "relationship--c195f2cb-deff-400e-b89e-8625deaa9817", "modified": "2026-04-29T14:23:06.190Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--c2417bab-3189-4d4d-9d60-96de2cdaf0ab", "spec_version": "2.1", "target_ref": "attack-pattern--7e150503-88e7-4861-866b-ff1ac82c4475", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21298', 0, 97, '09-mitre-attack', 'retrieved', 'A8BEA061F687092673C9C8B615DA1AD147F5F794F9F25EEF50F51CDA651E01A4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
