VALUES ('doc-09-mitre-attack-p0-21299', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kwampirs](https://attack.mitre.org/software/S0236) collects network adapter and interface information by using the commands ipconfig /all , arp -a and route print . It also collects the system''s MAC address with getmac and domain configuration with net config workstation .(Citation: Symantec Orangeworm April 2018)", "external_references": [{"description": "Symantec Security Response Attack Investigation Team. (2018, April 23). New Orangeworm attack group targets the healthcare sector in the U.S., Europe, and Asia. Retrieved May 8, 2018.", "source_name": "Symantec Orangeworm April 2018", "url": "https://www.symantec.com/blogs/threat-intelligence/orangeworm-targets-healthcare-us-europe-asia"}], "id": "relationship--cfa38151-4972-4355-8071-dd36cb1be880", "modified": "2026-04-29T14:23:06.209Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--c2417bab-3189-4d4d-9d60-96de2cdaf0ab", "spec_version": "2.1", "target_ref": "attack-pattern--707399d6-ab3e-4963-9315-d9d3818cd6a0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21299', 0, 106, '09-mitre-attack', 'retrieved', '25FD7F9230B2DE719EEF48CD9E7DA38116E672C7CC98CAC0BE76B89D76288D59', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
