VALUES ('doc-09-mitre-attack-p0-21324', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-12-20T21:22:44.875Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DEADEYE](https://attack.mitre.org/software/S1052) can ensure it executes only on intended systems by identifying the victim''s volume serial number, hostname, and/or DNS domain.(Citation: Mandiant APT41)", "external_references": [{"description": "Rufus Brown, Van Ta, Douglas Bienstock, Geoff Ackerman, John Wolfram. (2022, March 8). Does This Look Infected? A Summary of APT41 Targeting U.S. State Governments. Retrieved July 8, 2022.", "source_name": "Mandiant APT41", "url": "https://www.mandiant.com/resources/apt41-us-state-governments"}], "id": "relationship--03cb8f9a-7ad7-4aa8-966f-bf768023eb89", "modified": "2026-04-29T14:23:05.908Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--c46eb8e6-bf29-4696-8008-3ddb0b4ca470", "spec_version": "2.1", "target_ref": "attack-pattern--853c4192-4311-43e1-bfbb-b11b14911852", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21324', 0, 87, '09-mitre-attack', 'retrieved', '5F021D9B3F334A497CF25FB5B65BC845CBA13BD375ACB88AEECB0C9C1EF4A9FC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
