VALUES ('doc-09-mitre-attack-p0-21409', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-05T18:28:11.873Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WIREFIRE](https://attack.mitre.org/software/S1115) can modify the `visits.py` component of Ivanti Connect Secure VPNs for file download and arbitrary command execution.(Citation: Mandiant Cutting Edge January 2024)(Citation: Volexity Ivanti Zero-Day Exploitation January 2024)", "external_references": [{"description": "McLellan, T. et al. (2024, January 12). Cutting Edge: Suspected APT Targets Ivanti Connect Secure VPN in New Zero-Day Exploitation. Retrieved February 27, 2024.", "source_name": "Mandiant Cutting Edge January 2024", "url": "https://www.mandiant.com/resources/blog/suspected-apt-targets-ivanti-zero-day"}, {"description": "Meltzer, M. et al. (2024, January 10). Active Exploitation of Two Zero-Day Vulnerabilities in Ivanti Connect Secure VPN. Retrieved February 27, 2024.", "source_name": "Volexity Ivanti Zero-Day Exploitation January 2024", "url": "https://www.volexity.com/blog/2024/01/10/active-exploitation-of-two-zero-day-vulnerabilities-in-ivanti-connect-secure-vpn/"}], "id": "relationship--f9f9a03b-107a-4cba-ad4e-39d9424da100", "modified": "2026-04-29T14:23:06.264Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--c93e3079-43fb-4d8d-9e99-db63d07eadc9", "spec_version": "2.1", "target_ref": "attack-pattern--960c3c86-1480-4d72-b4e0-8c242e84a5c5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-21409', 0, 124, '09-mitre-attack', 'retrieved', 'D672DAA36AED41854161B720EE7BA1965C4B9EBF7693E5929EE007F1EAA8FFED', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "